SELECT rating_bucket, new_york_count, city_list FROM (SELECT CASE WHEN rating >= 3.5 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END rating_bucket, SUM(CASE WHEN city = 'New York' THEN 1 ELSE 0 END) new_york_count, SORT_ARRAY(COLLECT_SET(city)) city_list FROM suppliers WHERE rating <= 3.4 GROUP BY CASE WHEN rating >= 3.5 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END) t WHERE new_york_count < 61 ORDER BY new_york_count DESC;
